import React, { useState } from 'react';
import { Galleria } from 'primereact/galleria';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="galleria-accessibility">Accessible Galleria</label>
            <Galleria 
                id="galleria-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible Galleria input"
                placeholder="Enter galleria"
            />
        </div>
    );
}